CREATE SCHEMA IF NOT EXISTS dayamora;
REVOKE ALL ON SCHEMA dayamora FROM PUBLIC;
SET LOCAL search_path TO dayamora, pg_catalog;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','customer')),phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS selections(user_id TEXT PRIMARY KEY REFERENCES users(id),cart TEXT NOT NULL,favorites TEXT NOT NULL,preferences TEXT NOT NULL DEFAULT '{}');
 CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,brand TEXT NOT NULL,cat TEXT NOT NULL,price BIGINT NOT NULL CHECK(price > 0),stock BIGINT NOT NULL CHECK(stock >= 0),variants TEXT NOT NULL,image_url TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active BIGINT NOT NULL DEFAULT 1,is_sample BIGINT NOT NULL DEFAULT 0,gallery TEXT NOT NULL DEFAULT '[]',compare_price BIGINT);
 CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,items TEXT NOT NULL,total BIGINT NOT NULL,status TEXT NOT NULL,contact TEXT NOT NULL,created_at BIGINT NOT NULL,completed_at BIGINT,UNIQUE(user_id,request_key));
 CREATE TABLE IF NOT EXISTS points(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),delta BIGINT NOT NULL,reason TEXT NOT NULL,order_id TEXT UNIQUE REFERENCES orders(id),created_by TEXT NOT NULL REFERENCES users(id),created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),product_id BIGINT NOT NULL REFERENCES products(id),rating BIGINT NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,created_at BIGINT NOT NULL,hidden BIGINT NOT NULL DEFAULT 0,UNIQUE(user_id,product_id));
 CREATE TABLE IF NOT EXISTS wardrobe(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,cat TEXT NOT NULL,image_url TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS styles(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,product_ids TEXT NOT NULL,wardrobe_ids TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS points_user ON points(user_id);CREATE INDEX IF NOT EXISTS orders_user ON orders(user_id);CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS one_admin ON users(role) WHERE role='admin';
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,n INTEGER NOT NULL,until_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(path TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),private INTEGER NOT NULL CHECK(private IN (0,1)),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS wardrobe_user ON wardrobe(user_id);
CREATE INDEX IF NOT EXISTS styles_user ON styles(user_id);
CREATE INDEX IF NOT EXISTS reviews_product ON reviews(product_id);
INSERT INTO migrations(version,applied_at) VALUES(1,(extract(epoch FROM now())*1000)::bigint) ON CONFLICT DO NOTHING;
